parameters.jsCode:
const rawText = $input.first().json.candidates[0].content.parts[0].text;
const cleaned = rawText.replace(/```json|```/g, '').trim();
const ai = JSON.parse(cleaned);
const webhookData = $('Webhook (nuevo lead)').first().json.body;

return {
  lead_id: webhookData.lead_id || webhookData.id,
  lead_score: ai.score,
  lead_category: ai.category,
  lead_insight: ai.insight,
  lead_recommendation: ai.recomendacion,
  status: ai.score >= 7 ? 'demo' : ai.score >= 4 ? 'contacted' : 'new',
  value: Math.round(ai.score * 100),
  notas: `[IA] Score: ${ai.score}/10 | ${ai.insight}`
};
